            }
        ],
        "name": "ВАФЛИ ХРУСТЯЩИЕ В ВАФЕЛЬНИЦЕ",
        "servings": 10,
        "steps": [
            {
                "model": "step_model",
                "description": "Как испечь вафли хрустящие в вафельнице? Подготовьте необходимые продукты. Из данного количества у меня получилось 8 штук диаметром около 10 см.",
                "name": "",
                "step_number": 1,
                "unique_code": "8fe6492dc50d42c2bc72ff88f9580303"
            },
            {
                "model": "step_model",
                "description": "Масло положите в сотейник с толстым дном. Растопите его на маленьком огне на плите, на водяной бане либо в микроволновке.",
                "name": "",
                "step_number": 2,
                "unique_code": "22f779c8fd714d2694a2090ecc1ae6a4"
            },
            {
                "model": "step_model",
                "description": "Добавьте в теплое масло сахар. Перемешайте венчиком до полного растворения сахара. От тепла сахар довольно быстро растает.",
                "name": "",
                "step_number": 3,
                "unique_code": "50c6922e2fee48e286958f81e7844d3a"
            },
            {
                "model": "step_model",
                "description": "Добавьте в масло яйцо. Предварительно все-таки проверьте масло, не горячее ли оно, иначе яйцо может свариться. Перемешайте яйцо с маслом до однородности.",
                "name": "",
                "step_number": 4,
                "unique_code": "89a66c01b72e4ee7bca77ad32040df83"
            },
            {
                "model": "step_model",
                "description": "Всыпьте муку, добавьте ванилин.",
                "name": "",
                "step_number": 5,
                "unique_code": "317b7681761e47bba66c05c1837031fc"
            },
            {
                "model": "step_model",
                "description": "Перемешайте массу венчиком до состояния гладкого однородного теста.",
                "name": "",
                "step_number": 6,
                "unique_code": "dcdd97ae9462453b9a35a0b02963733f"
            },
            {
                "model": "step_model",
                "description": "Разогрейте вафельницу по инструкции к ней. У меня очень старая, еще советских времен электровафельница. Она может и не очень красивая, но печет замечательно!",
                "name": "",
                "step_number": 7,
                "unique_code": "527906aa7fc44fbeb1aae1938ad9f04a"
            },
            {
                "model": "step_model",
                "description": "Пеките вафли несколько минут до золотистого цвета. Осторожно откройте вафельницу, она очень горячая! Снимите вафлю лопаткой. Горячая она очень мягкая, как блинчик.",
                "name": "",
                "step_number": 9,
                "unique_code": "abbba9ce13ea4481b2aedf3f6ba4524f"
            },
            {
                "model": "step_model",
                "description": "Отварите спагетти в подсоленной воде до состояния al dente, следуя инструкции на упаковке.",
                "name": "",
                "step_number": 1,
                "unique_code": "915b0b35dde345e5869fface8e8585af"
            },
            {
                "model": "step_model",
                "description": "Пока паста варится, разогрейте сковороду на среднем огне и растопите сливочное масло.",
                "name": "",
                "step_number": 2,
                "unique_code": "c3445f141a114b1c87b3330e2e115b4b"
            },
            {
                "model": "step_model",
                "description": "Добавьте измельченный чеснок и обжарьте его в течение 1 минуты, пока не появится аромат.",
                "name": "",
                "step_number": 3,
                "unique_code": "2134abd001d34cf593058b2d78cde203"
            },
